import React, { useState, useEffect } from "react";
import { BrowserRouter as Router, Routes, Route, Navigate, Outlet } from "react-router-dom";
import "./App.css";
import Navbar from "./components/Navbar";
import ChatBox from "./components/ChatBox";
import YouTube from "./components/YouTube";
import Wikipedia from "./components/Wikipedia";
import Test from "./components/Test";
import Login from "./components/Auth/Login";
import Register from "./components/Auth/Register";

const App = () => {
  const [activePage, setActivePage] = useState("chat");
  const [messages, setMessages] = useState([]);
  const [latestQuery, setLatestQuery] = useState("");
  const [topics, setTopics] = useState([]);
  const [user, setUser] = useState(null);

  // 🔹 Load user authentication state safely
  useEffect(() => {
    const savedUser = localStorage.getItem("user");
    if (savedUser) {
      try {
        setUser(JSON.parse(savedUser));
      } catch (error) {
        console.error("Error parsing user data:", error);
        localStorage.removeItem("user");
        setUser(null);
      }
    }
  }, []);

  // 🔹 Load messages & topics from localStorage safely
  useEffect(() => {
    try {
      const savedMessages = JSON.parse(localStorage.getItem("messages")) || [];
      const savedTopics = JSON.parse(localStorage.getItem("topics")) || [];
      setMessages(savedMessages);
      setTopics(savedTopics);
    } catch (error) {
      console.error("Error loading messages or topics:", error);
    }
  }, []);

  // 🔹 Save messages & topics only when they change
  useEffect(() => {
    if (messages.length > 0) {
      localStorage.setItem("messages", JSON.stringify(messages));
    }
    if (topics.length > 0) {
      localStorage.setItem("topics", JSON.stringify(topics));
    }
  }, [messages, topics]);

  // 🔹 Logout function
  const handleLogout = () => {
    localStorage.removeItem("user");
    setUser(null);
  };

  // 🔹 Protected Routes Wrapper
  const ProtectedRoutes = () => {
    return user ? (
      <>
        <Navbar activePage={activePage} setActivePage={setActivePage} onLogout={handleLogout} />
        <Outlet />
      </>
    ) : (
      <Navigate to="/login" replace />
    );
  };

  return (
    <Router>
      <div className="app-container">
        <Routes>
          {/* Public Routes */}
          <Route path="/login" element={user ? <Navigate to="/" replace /> : <Login setUser={setUser} />} />
          <Route path="/register" element={user ? <Navigate to="/" replace /> : <Register setUser={setUser} />} />

          {/* Protected Routes */}
          <Route element={<ProtectedRoutes />}>
            <Route path="/" element={<ChatBox messages={messages} setMessages={setMessages} setLatestQuery={setLatestQuery} />} />
            <Route path="/youtube" element={<YouTube latestQuery={latestQuery} />} />
            <Route path="/wikipedia" element={<Wikipedia latestQuery={latestQuery} />} />
            <Route path="/test" element={<Test messages={messages} latestQuery={latestQuery} topics={topics} setTopics={setTopics} />} />
          </Route>

          {/* Redirect unknown routes */}
          <Route path="*" element={<Navigate to={user ? "/" : "/login"} />} />
        </Routes>

        {/* Footer */}
        <footer className="footer">
          <p>&copy; 2025 PAT | @Indrajit002</p>
        </footer>
      </div>
    </Router>
  );
};

export default App;
